it("migrates one theme choice to both appearances and preserves independent choices", () => {
  expect(resolveMobileThemeIds({ themeId: "ink" })).toEqual({
    light: "ink",
    dark: "ink",
  });
  expect(
    resolveMobileThemeIds({ themeId: "ink", lightThemeId: "nocturne", darkThemeId: "ocean" }),
  ).toEqual({ light: "nocturne", dark: "ocean" });
  // Rubato: a theme this build lacks (missing, or T3's standard "t3-code") shows Ocean.
  expect(resolveMobileThemeIds({ themeId: "ink", lightThemeId: "missing" })).toEqual({
    light: "ocean",
    dark: "ink",
  });
  expect(resolveMobileThemeIds({ themeId: "t3-code" })).toEqual({
    light: "ocean",
    dark: "ocean",
  });
  expect(resolveMobileThemeIds({})).toEqual({ light: "ocean", dark: "ocean" });
});

